import{_ as n,C as a,o as r,c as i,j as o,a as t,E as l,a7 as h}from"./chunks/framework.C4ZIv4ii.js";const w=JSON.parse(`{"title":"Custom Fonts — use your own font files in FalconCMS","description":"Upload your own font files and use them in the theme's typography, every Falcon Builder element and Motion Visual text, next to the Google Fonts list.","frontmatter":{"title":"Custom Fonts — use your own font files in FalconCMS","description":"Upload your own font files and use them in the theme's typography, every Falcon Builder element and Motion Visual text, next to the Google Fonts list."},"headers":[],"relativePath":"guide/custom-fonts.md","filePath":"guide/custom-fonts.md","lastUpdated":1795616640000}`),d={name:"guide/custom-fonts.md"},f={id:"custom-fonts",tabindex:"-1"};function g(u,e,c,m,p,y){const s=a("Badge");return r(),i("div",null,[o("h1",f,[e[0]||(e[0]=t("Custom Fonts ",-1)),l(s,{type:"tip",text:"2.8.8"}),e[1]||(e[1]=t()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#custom-fonts","aria-label":'Permalink to "Custom Fonts <Badge type="tip" text="2.8.8" />"'},"​",-1))]),e[3]||(e[3]=h('<p>Use your own font files (a brand font, a font that Google Fonts does not have) anywhere a font is chosen:</p><ul><li>the theme&#39;s typography in the Customizer</li><li>every typography setting of the <a href="/falconcms/builder/overview.html">Falcon Builder</a></li><li>text in a <a href="/falconcms/builder/motion-visual.html">Motion Visual</a></li></ul><p>Custom fonts are part of the free core.</p><div class="warning custom-block"><p class="custom-block-title">Check the licence</p><p>Make sure each font&#39;s licence allows using it on a website. Many desktop font licences do not.</p></div><h2 id="adding-a-font" tabindex="-1">Adding a font <a class="header-anchor" href="#adding-a-font" aria-label="Permalink to &quot;Adding a font&quot;">​</a></h2><ol><li>Upload the font files to the <a href="/falconcms/guide/media.html">Media Library</a>. FalconCMS reads <strong>WOFF2</strong>, <strong>WOFF</strong>, <strong>TTF</strong> and <strong>OTF</strong>.</li><li>Open <strong>Falcon Builder → Customizer → Typography → Custom Font</strong>.</li><li>Add one box for each <strong>font face</strong>, which is one weight and style of a font: <ul><li><strong>Font Name</strong>: the name you will pick the font by, for example <code>Brand Sans</code>. Boxes with the same name together make one family with several weights.</li><li><strong>Font Weight</strong>: choose <strong>Use what the file says</strong> to read the weight from the file. Turn on <strong>Variable</strong> for a variable font, which holds a range of weights in one file. The range is then read from the file, or you set it with <strong>From</strong>.</li><li><strong>Font Style</strong>: Normal or Italic.</li><li><strong>Files</strong>: choose a file for each format you have, from the Media Library.</li></ul></li><li>Press <strong>Save Changes</strong>.</li></ol><p>The weight and style are read from TTF, OTF and WOFF files. A WOFF2 file cannot be read on the server, so its weight is guessed from the file name. The screen says so, and you should check it.</p><h2 id="where-the-font-shows" tabindex="-1">Where the font shows <a class="header-anchor" href="#where-the-font-shows" aria-label="Permalink to &quot;Where the font shows&quot;">​</a></h2><p>A saved font appears under <strong>Custom Fonts</strong> in every font picker, above the Google Fonts list. Only the weights you added are offered, so the browser never draws a fake bold.</p><h2 id="what-happens-on-the-page" tabindex="-1">What happens on the page <a class="header-anchor" href="#what-happens-on-the-page" aria-label="Permalink to &quot;What happens on the page&quot;">​</a></h2><ul><li><strong>Only your own files are used.</strong> A file must be in the Media Library, and its contents must really be the format of the slot it was chosen for. A box with no usable file is dropped on save, with a note.</li><li><strong>A WOFF is made for you.</strong> If you give a TTF or OTF but no WOFF, FalconCMS makes a compact WOFF copy on save. Copies no font uses any more are removed. Your Media Library files are never changed.</li><li><strong>The smallest file loads first.</strong> The browser is offered WOFF2, then WOFF, then TTF, then OTF.</li><li><strong>Text stays readable while the font loads.</strong> It uses a fallback (sans-serif, serif, monospace, cursive or system-ui) until the font arrives.</li><li><strong>Custom fonts are never requested from Google.</strong> They load from your own site, so they work with <strong>Host Google Fonts Locally</strong> on or off.</li></ul><p>A site can hold up to 100 font faces. The fonts are saved with the Customizer&#39;s settings.</p>',12))])}const b=n(d,[["render",g]]);export{w as __pageData,b as default};
